import{z as o,x as i,o as B,c as d,q as t,j as l,D as A,d as a,s as n,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"loss 曲线的解读","description":"","frontmatter":{"title":"loss 曲线的解读","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ti-loss-curve-reading.md","filePath":"llm/ti-loss-curve-reading.md","lastUpdated":1791413859000}'),p={name:"llm/ti-loss-curve-reading.md"};function C(m,E,D,h,u,g){const r=i("Mermaid");return B(),d("div",null,[E[2]||(E[2]=t('<h1 id="loss-曲线的解读" tabindex="-1">loss 曲线的解读 <a class="header-anchor" href="#loss-曲线的解读" aria-label="Permalink to &quot;loss 曲线的解读&quot;">​</a></h1><div class="epigraph"><p>曲线不会说话，说清「这条曲线意味着什么」的是坐标口径、分期标注与止损判据——三者缺一，看曲线就退化为看运气。</p><footer>—— 据 OPT 训练日志与 PaLM 训练报告的尖峰记录整理</footer></div><p><a href="/llm/ti-checkpoint-engineering">上一课</a>把兜底收进演练，从此训练敢长跑。长跑产出的第一类数据，是每步落盘的损失标量。曲线的<strong>形状学</strong>——压熵段、幂律段、尖峰、双下降——在<a href="/llm/loss-curve-phases">损失曲线的阶段</a>已经分期；纵轴单位在 <a href="/llm/perplexity-bpb">perplexity 与 BPB</a> 钉成每 token 交叉熵。本课写观测侧的工程：把「看曲线」变成一套可执行的判读设施，谁在看、看哪条、怎么比对、何时止损。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>判读失败有四种典型。<strong>口径漂移</strong>：横轴混用步数与墙钟、纵轴混用 CE 与 PPL，两条曲线画在同一张图上，斜率不可比。<strong>平滑说谎</strong>：EMA 窗口开太大，尖峰被抹成平缓回升，异常发现晚数天；开太小，噪声淹没趋势，人人都在追抖动。<strong>对比失配</strong>：把不同 tokenizer、不同序列长度、不同配比的 run 画进一张图比高低，差异被归因给「方法」，实际是口径。<strong>没有止损判据</strong>：run 已发散或平台期已超出预算允许的步数，却因沉没成本继续烧卡。</p><h3 id="判读设施的最小配置" tabindex="-1">判读设施的最小配置 <a class="header-anchor" href="#判读设施的最小配置" aria-label="Permalink to &quot;判读设施的最小配置&quot;">​</a></h3><p>口径层：横轴统一 token 数，纵轴统一每 token CE，图题强制携带配置哈希与 tokenizer 版本——上一课的元数据纪律在这里兑现。平滑层：原始序列与两档 EMA（短窗看抖动、长窗看趋势）并存展示，分期标注（warmup 结束点、尖峰区间）由训练作业写进日志而非手绘。对比层：两条曲线可比的前提是配置哈希只在<strong>声明过的维度</strong>上不同；随机噪声下界用种子重复实验给出，<a href="/llm/eval-variance-seed">评测方差与种子</a>的口径同样适用于验证损失。</p><p><span class="marginnote">术语翻译：EMA（指数滑动平均）就是给曲线装减震器——新值按权重混进历史平均，窗口越大曲线越平滑但越迟钝。短窗 EMA 保留抖动形状、用于定位异常，长窗 EMA 抹平噪声、用于看趋势；两者必须与原始序列并存，谁也不能互相替代。</span></p><p><span class="marginnote">PaLM 与 OPT 的训练报告都记录了训练中多次损失尖峰，处理手段是跳过可疑批次或从检查点回退，而不是重启训练。把尖峰当噪声不归档，同类尖峰必然回来——尖峰区间要打标并留档成因，这也是幂律拟合前必须剔除的数据。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>判读流程按事件分三条。<strong>趋势判读</strong>：对长窗曲线核对阶段预期——warmup 内不降是初始化或学习率问题，幂律段斜率显著变缓要查配比与数据质量，而不是先调参。<strong>尖峰 triage</strong>：尖峰发生时先看<a href="/llm/grad-norm-monitoring">梯度范数监控</a>是否同步竖起、裁剪是否长时间贴顶（机制见<a href="/llm/grad-clip-loss-spike">梯度裁剪与损失尖峰</a>），再按「回放同批数据」分数据性与数值性，处置在跳批、回退与降学习率之间按预案选择，不许现场发明。<strong>止损判读</strong>：run 启动时写明死线——发散（CE 超过初值）、平台（长窗斜率低于阈值持续 \\(M\\) 步）、吞吐塌方（MFU 持续低于七成）；触线即杀，判据先于情绪存在。</p>',11)),(B(),l(s,null,{default:A(()=>[n(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E9%80%90%E6%AD%A5%20CE%20%E5%8E%9F%E5%A7%8B%E5%BA%8F%E5%88%97%22%5D%20--%3E%20S%5B%22%E5%8F%8C%E6%A1%A3%20EMA%20%2B%20%E5%88%86%E6%9C%9F%E6%A0%87%E6%B3%A8%22%5D%0A%20%20S%20--%3E%20T%7B%22%E4%BA%8B%E4%BB%B6%E7%B1%BB%E5%9E%8B%22%7D%0A%20%20T%20--%3E%7C%E8%B6%8B%E5%8A%BF%E5%BC%82%E5%B8%B8%7C%20A%5B%22%E6%A0%B8%E5%AF%B9%E9%98%B6%E6%AE%B5%E9%A2%84%E6%9C%9F%3A%20%E6%9F%A5%E9%85%8D%E6%AF%94%E4%B8%8E%E6%95%B0%E6%8D%AE%22%5D%0A%20%20T%20--%3E%7C%E5%B0%96%E5%B3%B0%7C%20B%5B%22%E7%9C%8B%E6%A2%AF%E5%BA%A6%E8%8C%83%E6%95%B0%E4%B8%8E%E8%A3%81%E5%89%AA%E8%B4%B4%E9%A1%B6%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%9B%9E%E6%94%BE%E5%90%8C%E6%89%B9%E6%95%B0%E6%8D%AE%E5%88%86%E5%9B%A0%22%5D%0A%20%20C%20--%3E%7C%E6%95%B0%E6%8D%AE%E6%80%A7%7C%20D%5B%22%E8%B7%B3%E6%89%B9%E5%B9%B6%E7%95%99%E6%A1%A3%E5%9D%8F%E5%8C%BA%E9%97%B4%22%5D%0A%20%20C%20--%3E%7C%E6%95%B0%E5%80%BC%E6%80%A7%7C%20E%5B%22%E5%9B%9E%E9%80%80%E6%A3%80%E6%9F%A5%E7%82%B9%E6%88%96%E9%99%8D%E5%AD%A6%E4%B9%A0%E7%8E%87%22%5D%0A%20%20T%20--%3E%7C%E8%A7%A6%E6%AD%A2%E6%8D%9F%E7%BA%BF%7C%20K%5B%22%E6%9D%80%20run%2C%20%E8%AE%B0%E6%AD%BB%E5%9B%A0%22%5D%0A%20%20T%20--%3E%7C%E6%AD%A3%E5%B8%B8%7C%20C2%5B%22%E7%BB%A7%E7%BB%AD%2C%20%E6%AF%8F%20N%20%E6%AD%A5%E6%97%81%E8%B7%AF%E8%AF%84%E6%B5%8B%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"这套设施有效的原因是它把判读从「有经验的人盯着」变成「契约约束所有人」。口径层消灭了最便宜的错误——画错图；平滑层保留了异常的可见性，因为分期与尖峰标注是训练作业的义务，人只负责读；对比层把归因收敛到声明变量，防止「顺手改了三个配置，赢了却不知道为什么」。止损判据的机制价值在于对称性：启动前写下死线，杀 run 是执行合同；没有死线，杀 run 是否定某个人的判断，组织上永远执行不动。",-1)),E[5]||(E[5]=e("p",null,[a("旁路评测与曲线的关系也要钉住：验证损失每 \\(N\\) 步在固定子集上计算，与训练 CE 分开两条轴，"),e("a",{href:"/llm/in-training-eval"},"训练中评测与早期信号"),a("的纪律不变——评测永不接入训练的数据预取队列。")],-1)),(B(),l(s,null,{default:A(()=>[n(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20RAW%5B%22%E5%8E%9F%E5%A7%8B%E5%BA%8F%E5%88%97%3A%20%E6%AF%8F%E6%AD%A5%20CE%22%5D%20--%3E%7C%22%E9%80%90%E7%82%B9%E7%9C%8B%22%7C%20SP%5B%22%E5%B0%96%E5%B3%B0%E5%AE%9A%E4%BD%8D%3A%20%E7%B2%BE%E7%A1%AE%E5%8C%BA%E9%97%B4%22%5D%0A%20%20RAW%20--%3E%20SHORT%5B%22%E7%9F%AD%E7%AA%97%20EMA%3A%20%E6%95%B0%E5%8D%81%E6%AD%A5%E7%AA%97%22%5D%0A%20%20RAW%20--%3E%20LONG%5B%22%E9%95%BF%E7%AA%97%20EMA%3A%20%E6%95%B0%E5%8D%83%E6%AD%A5%E7%AA%97%22%5D%0A%20%20SHORT%20--%3E%7C%22%E4%BF%9D%E7%95%99%E6%8A%96%E5%8A%A8%E5%BD%A2%E7%8A%B6%22%7C%20TR%5B%22%E6%8A%96%E5%8A%A8%E5%88%A4%E8%AF%BB%3A%20%E6%95%B0%E5%80%BC%E5%81%A5%E5%BA%B7%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20LONG%20--%3E%7C%22%E6%8A%B9%E5%B9%B3%E5%99%AA%E5%A3%B0%22%7C%20TR2%5B%22%E8%B6%8B%E5%8A%BF%E5%88%A4%E8%AF%BB%3A%20%E5%B9%82%E5%BE%8B%E6%96%9C%E7%8E%87%E4%B8%8E%E5%B9%B3%E5%8F%B0%22%5D%0A%20%20SP%20--%3E%20ARCH%5B%22%E5%B0%96%E5%B3%B0%E5%8C%BA%E9%97%B4%E6%89%93%E6%A0%87%E7%95%99%E6%A1%A3%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">数字实例：一百万步的 run，平台死线若定为「长窗斜率低于阈值持续 5000 步」，只占全程 0.5%——发现平台即止损，最多浪费约半天的卡时；没有死线，同样的平台常被「再观察观察」拖掉数周。持续步数 \\(M\\) 要对照实测的尖峰恢复时间来定，不能拍脑袋。</span></p><p><span class="marginnote">常见误区：初学者容易把不同 tokenizer、不同序列长度的两条 CE 曲线画进一张图直接比高低，实际上口径不同时纵轴根本不是同一个量——每 token CE 与 PPL 还是指数关系。先统一口径，再谈输赢；否则差异会被错记到「方法」头上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>曲线判读只回答「训练是否健康」，不回答「模型是否变强」：下游能力的出现、评测集上的名次，属于评测各课，验证损失与基准分数会背离。分期边界本身是判断，自动标注只能给出候选断点；尖峰分因的「回放」依赖上一课的坏批回放四元组，回放不可用时只能按相关性猜。多 run 对比在配置差异超过两个维度时基本失效，此时该做的是消融，不是画图。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>口径先行：横轴 token 数、纵轴每 token CE、图题带配置哈希与 tokenizer 版本。</li><li>原始与双档 EMA 并存，分期与尖峰标注由训练作业写入日志。</li><li>尖峰按预案 triage：梯度范数定位、回放分因、跳批或回退，处置后留档。</li><li>死线在启动时写明：发散、平台、吞吐塌方，触线即杀。</li><li>出处：据 OPT 训练日志（Zhang et al., 2022）与 PaLM 训练报告（Chowdhery et al., 2023）的尖峰处置整理；分期口径见<a href="/llm/loss-curve-phases">损失曲线的阶段</a>。</li></ul>',6))])}const f=o(p,[["render",C]]);export{c as __pageData,f as default};
